import XCTest

final class TapChatTests: XCTestCase {
    func testOpenChat() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.launch()

        let chatButton = app.descendants(matching: .any).matching(
            NSPredicate(format: "label CONTAINS[c] 'chat'")
        ).firstMatch

        if chatButton.waitForExistence(timeout: 20) {
            chatButton.tap()
        } else {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.935)).tap()
        }
        Thread.sleep(forTimeInterval: 3)
    }
}
